use glam::DVec3 as V;use ingetrazo_core::{scene::{Scene,SelectionItem},image_plane::{ImagePlane,ImageDelta},math::Ray};use ingetrazo_tools::{move_tool::MoveTool,base::{Tool,ToolContext}};
fn ctx(p:V)->ToolContext{ToolContext::new(p,Ray::new(V::new(1.,1.,10.),-V::Z))}
fn state(s:&Scene,a:&ImagePlane)->serde_json::Value{let held=s.image_planes.iter().find(|p|p.id==a.id).cloned().or_else(||s.image_objects.0.lock().unwrap().get(&a.id).cloned()).unwrap_or_else(||a.clone());serde_json::json!({"live":s.image_planes.iter().map(|p|serde_json::json!([p.path,p.origin.x,p.origin.y,p.origin.z])).collect::<Vec<_>>(),"held":held.origin})}
fn main(){let mut rows=serde_json::Map::new();for mutation in ["reverse","delete_target","delete_other"]{for end in ["cancel","commit"]{let mut s=Scene::new();let a=ImagePlane::new("A",V::new(0.125,0.,0.),V::X*2.,V::Y*2.);let b=ImagePlane::new("B",V::X*10.,V::X*2.,V::Y*2.);s.image_planes=vec![a.clone(),b.clone()].into();s.select(SelectionItem::ImagePlane(0));let mut t=MoveTool::new();let mut states=vec![state(&s,&a)];t.on_click(&mut s,&ctx(V::ZERO));t.on_move(&mut s,&ctx(V::new(1.,2.,0.)));states.push(state(&s,&a));s.image_objects.publish(&s.image_planes);let before=s.image_planes.clone();if mutation=="reverse"{s.image_planes.reverse();}else{let id=if mutation=="delete_target"{a.id}else{b.id};s.image_planes.retain(|p|p.id!=id);}let deletion=ImageDelta::between(&before,&s.image_planes);states.push(state(&s,&a));t.on_move(&mut s,&ctx(V::new(3.,4.,0.)));states.push(state(&s,&a));if end=="cancel"{t.on_cancel(&mut s);}else{t.on_click(&mut s,&ctx(V::new(5.,6.,0.)));}states.push(state(&s,&a));if mutation!="reverse"{s.image_planes=deletion.restore(&s.image_planes,&s.image_objects).into();}states.push(state(&s,&a));rows.insert(format!("{mutation}:{end}"),serde_json::json!(states));}}println!("{}",serde_json::to_string_pretty(&rows).unwrap());}
